'use strict';
const WINTER_MEANING={
 get(p,item){
  const grade=p.grade,sub=p.subject,kind=p.kind,comp=item.composition;
  let headline='',now='',after='',approach='';
  const format=[];
  if(/個別/.test(comp))format.push('個別指導では、解く過程を確認しながら疑問を整理します。説明を受けた後に、自分で解けるかを確かめます。');
  if(/映像/.test(comp))format.push('映像授業では、選んだ単元の考え方を学びます。視聴しただけで終えず、教材や確認問題で理解を確かめることを大切にします。');
  if(/学トレ/.test(comp))format.push('AI学トレでは、問題を解いて結果を確かめ、誤った内容にもう一度取り組みます。「分かったつもり」を自力で使える知識に近づけます。');
  if(/自立/.test(comp))format.push('自立学習では、課題の進め方と進捗を確認し、解き直しまで取り組みます。新学期にも続けられる勉強の手順を整えます。');
  if(kind==='オリジナル'){
   headline='残りの時間を、今いちばん必要な学びに。';now='志望校や試験科目、現在の答案によって、冬に優先する課題は異なります。'+(grade==='高3'?'受験に向けて幅広く増やすだけでなく、得点につながる課題と解き直しの順番を整理する時期です。':'受験時期と出題内容を確かめ、取り組む範囲を絞った計画をつくることに意義があります。');approach=item.focus?'今回の重点は「'+item.focus+'」。担当者と決めた内容・回数に沿って取り組み、途中で理解を確認します。':'担当者との相談で、重点単元・授業形式・回数を決めます。確定後は、優先する課題から取り組み、途中で理解を確認する計画です。';after='できた問題と、引き続き確認が必要な問題を整理し、その後の受験準備につなげます。';
  }else if(kind==='力シリーズ'){
   const map={
    '閃きの力':['考える楽しさを、あきらめない力へ。','冬のまとまった時間に、すぐ正解を教わるのではなく、図や数を頭の中で動かし、試しながら考える経験をつくります。学校の算数の補習とは別に、考える過程そのものを育てる学びです。','図形・数のパズルを用い、イメージする、試す、考え直すことに取り組みます。解けたかどうかだけでなく、どんな工夫をしたかも振り返ります。','初めての問題でも、まず自分で考えを試してみる姿勢を、日々の学習につなげます。'],
    '読書の力':['一冊との出会いを、言葉の土台に。','日々の学習で文章を読むとき、言葉を知っていることや内容を追う経験が支えになります。この冬は、本に親しむ時間をつくり、知らなかった言葉や表現との出会いを増やします。','朗読を聴きながら本を読み、読書ワークで言葉や表現に触れます。読んだ量だけでなく、印象に残った場面や新しく知った言葉を大切にします。','本や文章に向かう習慣を新学期にも続け、言葉の世界を少しずつ広げます。短期の点数上昇だけを目的とするものではありません。'],
    '英検®の力':['英語の目標を、毎回の小さな一歩に。','目標級があると、英語で何ができるようになりたいかを具体化できます。この冬は現在の習熟度と苦手な技能を確かめ、読む・聞く・話す・書く学習を進める機会にします。','受験級に合う課題を選び、知識を確認する学習と、話す・書くアウトプットを組み合わせます。受験時期や開講級は校舎と相談して決めます。','練習した表現を使える場面を増やし、次の受験や継続学習の課題を明確にします。検定合格を保証するものではありません。']};
   [headline,now,approach,after]=map[sub];
  }else if(sub==='作文'){
   headline='「思ったこと」を、伝わる言葉に。';now='言いたいことがあっても、使える言葉や書く経験が少ないと、文章にするところで止まりがちです。この冬は読む経験と表現の学習を結びつけ、言葉を選ぶ土台を育てます。';approach=Number(grade[1])<=3?'個別指導と読書を組み合わせ、感じたことや考えたことを言葉にする練習に取り組みます。':'AI学トレの語彙力養成コースと読書を組み合わせ、使える言葉を増やします。語彙や読む経験を、表現の土台にしていきます。';after='短い文や段落で自分の考えを伝える経験を、学校での記述や日々の会話につなげます。';
  }else if(grade.startsWith('小')){
   if(sub==='算数'){
    headline=kind==='補強'?'曖昧なままを、次の学年へ持ち越さない。':'習ったことを、使える算数へ。';
    const units={'小4':'数の扱い、グラフ、図形など','小5':'約数・倍数、分数、面積、単位量や割合など','小6':'分数の計算、文字と式、比、図形など'}[grade];
    now=kind==='補強'?'2学期の学習を振り返り、解き方が曖昧なところを見つけて解き直します。先へ進む前に、今まで学んだ基本を自分で使えるか確認することが、この冬の学びの意義です。':units+'の重点単元を、理解したつもりで終えず演習と解き直しで確かめます。冬に学びを整理し、今までの知識を使う経験を増やします。';
    after=grade==='小6'?'小学校で学んだ計算や数量・図形の考え方を確認し、中学校の学習に向かう準備につなげます。':'新学期の算数に取り組むときに使う基本を整え、自分で解けた経験を次の学習につなげます。';
   }else{
    headline=kind==='補強'?'覚えた漢字を、書ける漢字に。':'言葉のしくみを、確かな知識に。';
    now=kind==='補強'?'学年相当の漢字を見直し、覚えている字と迷う字を整理します。毎回のテストで確認しながら学び直す冬にすることで、漢字練習を「書いて終わり」にしない習慣をつくります。':'主語・述語など、よく問われる国語の知識を総復習します。文章を読む・書くときにも使う言葉のきまりを、この冬に整理することを目指します。';
    after=kind==='補強'?'新学期の読み書きで使う漢字を増やし、間違えた字を自分で覚え直す学び方につなげます。':'学習した知識を学校の課題やテストでも使えるようにします。この講座は知識問題が中心で、初見の長文読解を中心に扱う講座とは異なります。';
   }
  }else if(['中1','中2'].includes(grade)){
   const maps={
    英語:kind==='補強'?['単語の土台を、冬のうちに整える。','文を読む・書く学習を進めるうえで、必要な単語を思い出せることが支えになります。冬は、覚えた語と曖昧な語を確認し、暗記とテストを繰り返す時間にします。','単語の確認手順を身につけ、学校の学習や学年末テストに向けた日々の復習に生かします。']:['習った英語を、問題の中で使えるように。','学年末テストの範囲に合わせ、学んだ内容を自力で使う演習に取り組みます。冬のうちに間違い方を確認し、学習し直すところを絞ることが大切です。','確認できた弱点を新学期の復習につなげ、学校の進度に合わせて準備を続けます。'],
    数学:kind==='補強'?['課題を終える冬から、解き直す冬へ。','学校ワークや普段の教材で、分かったつもりの問題を見直します。課題の進捗と理解を分けて確認し、休み明け・学年末のテストへ向けて基本を整えます。','課題に取り組む順番と解き直しの習慣を、新学期の家庭学習にもつなげます。']:['図形の学びを、確かな手応えに。',`${grade==='中1'?'平面図形・空間図形':'三角形と四角形'}を含む既習単元と学年末範囲を、学校進度に合わせて演習します。考え方を知っていることと、自力で問題を解けることの間を埋める冬にします。`,'解けなかった理由を整理し、学年末テストまでの復習で優先する課題を明確にします。'],
    理科:kind==='補強'?['最近学んだ理科を、曖昧なままにしない。','2学期期末後の単元は、定着の確認が十分でない場合があります。冬に学校進度に合う範囲を基本から練習し、用語や考え方を確かめる機会をつくります。','確認が必要な単元を整理し、学年末テストへ向けた学習につなげます。']:['次の理科を、理解する準備に。','2学期期末後の単元から、学年末テストを見据えて予習を進めます。学校や地域の進度に合わせて学ぶ範囲を選び、これから学ぶ内容の考え方に触れます。','映像で学んだ内容を学校の授業や復習で確かめ、理解を重ねていきます。'],
    社会:kind==='補強'?['ワークを、知識を確かめる道具に。','学年末テストへ向けて、学校教材などを繰り返し解きます。空欄を埋めるだけでなく、思い出せない語句や資料の読み取りを見つける冬にします。','覚え直す内容と解き直す問題を整理し、新学期のテスト勉強に生かします。']:['学んだ社会を、使う練習へ。','学校進度に合う単元を問題演習で確かめます。学年末範囲が終わっている場合はこれまでの復習へ進み、知識を整理する機会にします。','練習した知識を資料や問題の中で使い、弱点を意識した復習につなげます。'],
    国語:['文法・古典の知識を、冬に整理する。','文法や古典は、きまりや言葉の知識を整理してから問題に取り組むことが大切です。映像で学ぶ時間と対応する問題を解く時間を組み合わせ、曖昧な知識を確かめます。',kind==='補強'?'基本レベルから確かめた内容を、新学期の文法・古典の学習に生かします。':'確認レベルから取り組んだ知識を、学校の課題やテストでも使えるか確かめていきます。']};
   [headline,now,after]=maps[sub];
  }else if(grade==='中3'){
   headline=kind==='私立推薦'?'本番へ向けて、必要な準備を絞る。':kind==='難関高校'?'志望校の難度へ、学びを一段深める。':'入試で使う基本を、冬に整理する。';
   const focuses={英語:kind==='私立推薦'?'過去問やフォレスタステップで疑問を解消すること':kind==='補強'?'入試テーマを学び、関係代名詞などの弱点を基本から練習すること':'過去問や冬期教材とハイレベル演習に取り組むこと',数学:kind==='私立推薦'?'過去問などから必要な課題を整理すること':kind==='補強'?'中1・2の復習と中3の演習を、基礎を優先して進めること':'過去問や冬期教材とハイレベルの問題に取り組むこと',理科:kind==='補強'?'テーマ別入試対策Ⅰ〜Ⅲの17単元を学ぶこと':'テーマ別入試対策Ⅰ〜Ⅳの23単元を学ぶこと',社会:kind==='補強'?'映像の入試テーマと資料問題の演習を組み合わせること':'資料問題と、難度に合う入試演習に取り組むこと',国語:kind==='私立推薦'?'古文・助動詞・漢文の学習と定着確認を進めること':kind==='補強'?'説明文・文学的文章・古文・漢文を学び、対応する問題を解くこと':'文法・語彙・読解・総合問題とハイレベル演習に取り組むこと'};
   now='受験に向けたこの冬は、取り組む範囲と難度を志望校・現在の理解に合わせることが大切です。今回の'+sub+'では、'+focuses[sub]+'を通じて、今優先する課題に向き合います。';after='解き直しが必要な問題と確かめられた内容を分け、本番までの復習計画に生かします。';
  }else{
   const maps={英語:kind==='補強'?['学校の単語学習を、確かな土台に。','学校で扱う英単語を確認テストで繰り返し確かめます。冬に自分の曖昧な語を整理し、普段の学習で覚え直す手順をつくります。','単語を見直す習慣を、新学期の英語学習や定期テストに向けた準備につなげます。']:['英文法を、理解度に合うところから。','英語の学習では、文の組み立てを理解して使えることが大切です。習熟度に合う映像・教材を選び、この冬に理解を整理し直します。','学習した文法を学校の課題でも確かめ、次の英語学習へ進む土台にします。'],数学:kind==='補強'?['基本問題を、自分で解く練習に。','学校ワークやフォレスタから理解度に合う問題を選び、2周の演習で定着を目指します。冬に解き直しの時間を確保し、解ける問題と疑問が残る問題を整理します。','学校の学習や定期テストで使う基本を整えます。仕組みの理解に課題がある場合は、通常の個別指導などで説明を補います。']:grade==='高1'?['定期テスト範囲を、もう一段深く。','基本が身についていることを確認したうえで、ステップアップの映像と確認テストに取り組みます。冬に学んだ内容を振り返り、理解の曖昧な単元を見つけ直します。','確認・終了テストで見えた課題を、次の定期テストに向けた学習へつなげます。']:['模試の結果を、次の学習の地図に。','模試結果から苦手単元を分析し、モジュールシリーズの適切なレベルを選びます。この冬は、何となく全体を進めるのではなく、弱点に学習時間を使うことを目指します。','確認テストで理解を確かめ、受験学年へ向けて続ける課題と優先順位を明確にします。']};
   [headline,now,after]=maps[sub];
  }
  if(!approach)approach=format.join('\n\n');
  return {headline,now,approach:approach||item.description,after};
 }
};
const meaningControls=document.createElement('section');meaningControls.className='meaning-controls';meaningControls.innerHTML='<label class="check"><input id="include-meaning" type="checkbox" checked>「この冬に学ぶ意義」の保護者向け資料を添える</label><p class="muted">選択した学年・教科・プラン別に自動作成。提案書の後に続けて印刷・PDF・HTML保存できます。</p>';
document.querySelector('.preview-toolbar').after(meaningControls);
const meaningRenderProposal=renderProposal;renderProposal=function(){meaningRenderProposal();$('include-meaning').checked=state.fields.includeMeaning!==false;document.querySelectorAll('#selected-edit .selected-item').forEach((el,i)=>{const x=state.selected[i],m=WINTER_MEANING.get(planById(x.id),x);el.insertAdjacentHTML('beforeend',`<details class="lesson-edit"><summary>保護者向け「冬に学ぶ意義」を調整</summary><p class="muted">初期案は選択講座に応じて変わります。空欄に戻すと初期案を使います。</p><label>なぜこの冬に取り組むか<textarea rows="4" maxlength="1200" data-edit="meaningNow" data-index="${i}" placeholder="${esc(m.now)}">${esc(x.meaningNow||'')}</textarea></label><label>次の学びへどうつなげるか<textarea rows="3" maxlength="1000" data-edit="meaningAfter" data-index="${i}" placeholder="${esc(m.after)}">${esc(x.meaningAfter||'')}</textarea></label></details>`);});};
const meaningRenderPaper=renderPaper;renderPaper=function(){meaningRenderPaper();if(state.fields.includeMeaning===false||!state.selected.length)return;const pages=state.selected.map((x,i)=>{const p=planById(x.id),m=WINTER_MEANING.get(p,x);return `<section class="meaning-page" style="break-before:page;page-break-before:always;padding-top:24px"><div class="paper-top"><b>さなる個別@will</b><span>WINTER LEARNING GUIDE</span></div><p class="meaning-kicker">保護者の皆さまへ · ${esc(state.grade)} / ${esc(x.title)}</p><h1>この冬に、この学びを<br>選ぶ理由。</h1><h2 class="meaning-headline">${esc(m.headline)}</h2><p class="composition">今回のご提案：${esc(x.composition.replace(/\n/g,' '))}</p><div class="meaning-block" style="break-inside:avoid"><h3>01　なぜ、この冬に？</h3><p>${esc(x.meaningNow||m.now)}</p></div><div class="meaning-block" style="break-inside:avoid"><h3>02　この講座で、どう学ぶ？</h3><p>${esc(m.approach)}</p>${x.focus?'<p><b>今回、重点的に取り組むこと</b><br>'+esc(x.focus)+'</p>':''}</div><div class="meaning-block" style="break-inside:avoid"><h3>03　次の学びへ、どうつなげる？</h3><p>${esc(x.meaningAfter||m.after)}</p><p><b>この冬の成長の確かめ方</b><br>${esc(x.measure||x.goal)}</p></div><div class="meaning-home" style="break-inside:avoid"><b>ご家庭には、こんな応援を。</b><p>${esc(x.home||COACH.subject[p.subject]?.home||'取り組みの中でできるようになったことを、短い会話で聞いてみてください。')}</p></div><p class="paper-end">お子さまの理解度や学校の進度に合わせて、内容を調整します。<br>学習の意義・到達目標はご提案の考え方であり、特定の点数や合格を約束するものではありません。</p></section>`;}).join('');$('paper').insertAdjacentHTML('beforeend',pages);};
$('include-meaning').addEventListener('change',()=>{state.fields.includeMeaning=$('include-meaning').checked;renderPaper();});
